import{_ as t,o as a,c as i,a5 as r}from"./chunks/framework.bIR-4glx.js";const h=JSON.parse('{"title":"AI Evaluation Record","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/ai-evaluation.en.md","filePath":"public/downloads/worksheets/ai-evaluation.en.md","lastUpdated":1795488252000}'),o={name:"public/downloads/worksheets/ai-evaluation.en.md"};function n(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-evaluation-record" tabindex="-1">AI Evaluation Record <a class="header-anchor" href="#ai-evaluation-record" aria-label="Permalink to &quot;AI Evaluation Record&quot;">​</a></h1><p>Use with <a href="https://byoungd.github.io/up/en/threads/practice/ai-evaluation" target="_blank" rel="noreferrer">AI Evaluation and Reliability</a>. Define criteria before running cases. The blank record covers one version comparison; example numbers describe neither model performance nor universal release thresholds.</p><h2 id="copyable-record" tabindex="-1">Copyable record <a class="header-anchor" href="#copyable-record" aria-label="Permalink to &quot;Copyable record&quot;">​</a></h2><h3 id="ai-evaluation-—-date-task" tabindex="-1">AI Evaluation — Date / Task <a class="header-anchor" href="#ai-evaluation-—-date-task" aria-label="Permalink to &quot;AI Evaluation — Date / Task&quot;">​</a></h3><h4 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h4><ul><li>User and intended action:</li><li>Input materials, permissions, and de-identification:</li><li>Manual baseline and total time:</li><li>Unsupported tasks:</li></ul><h4 id="test-setup-fixed-before-running" tabindex="-1">Test setup (fixed before running) <a class="header-anchor" href="#test-setup-fixed-before-running" aria-label="Permalink to &quot;Test setup (fixed before running)&quot;">​</a></h4><ul><li>Current version / candidate:</li><li>Model, prompt, retrieved materials, and tool versions:</li><li>Run date, region, memory settings, and service versions that cannot be pinned:</li><li>The one main change:</li><li>Development cases / held-out cases not used for tuning:</li><li>Attempts per case and time, call-count, and spending limits:</li><li>Conditions that must all pass:</li><li>Quality comparisons and human scoring rubric:</li><li>Reviewers / disagreement process:</li><li>Relevant failures: absent sources / prompt injection / unauthorized actions / unbounded retries or duplicate side effects / transcription or image errors:</li><li>Long-running fields: task/run IDs, checkpoints, wall-clock time, timeout, retry limit, idempotency key, and human takeover point:</li><li>Isolation fields: clean environment, network egress allowlist, credential scope, and untrusted browser/page-input note:</li><li>Policy fields: provider policy name, version, effective date, region, and high-risk human review:</li></ul><h4 id="case-records-copy-this-section-separately-for-each-version" tabindex="-1">Case records (copy this section separately for each version) <a class="header-anchor" href="#case-records-copy-this-section-separately-for-each-version" aria-label="Permalink to &quot;Case records (copy this section separately for each version)&quot;">​</a></h4><ul><li>Version for this section:</li><li>Use case ID / trial number, such as 07 / 2; link inputs to fixed case materials.</li></ul><h5 id="case-copy-once-per-attempt" tabindex="-1">Case (copy once per attempt) <a class="header-anchor" href="#case-copy-once-per-attempt" aria-label="Permalink to &quot;Case (copy once per attempt)&quot;">​</a></h5><ul><li>Case ID / trial number:</li><li>Case type and fixed input location:</li><li>Expected behavior / judging rationale:</li><li>Supporting passage / audio or video timestamp / image region:</li><li>Actual behavior / artifact location:</li><li>Transcript / tool calls / authorization record location:</li><li>Checkpoint / recovery ID / retry and idempotency record:</li><li>Network egress, page or screenshot evidence, and credential scope:</li><li>Final environment outcome (file, database, or user-visible state):</li><li>First-pass acceptance / mandatory failures:</li><li>Human revision minutes / changes:</li><li>Final state (retain failures and timeouts):</li></ul><h4 id="results-calculate-per-version-retain-failures-and-timeouts-in-denominators" tabindex="-1">Results (calculate per version; retain failures and timeouts in denominators) <a class="header-anchor" href="#results-calculate-per-version-retain-failures-and-timeouts-in-denominators" aria-label="Permalink to &quot;Results (calculate per version; retain failures and timeouts in denominators)&quot;">​</a></h4><ul><li>First-pass accepted / all attempts:</li><li>Mandatory failures and specific cases:</li><li>Accepted after human revision / all attempts:</li><li>Total minutes for preparation, execution, checking, and rework:</li><li>Tool charges and the time valuation used:</li><li>Total batch process cost / final accepted count:</li><li>Evidence limits and unsupported inferences:</li></ul><h4 id="decision-and-follow-up" tabindex="-1">Decision and follow-up <a class="header-anchor" href="#decision-and-follow-up" aria-label="Permalink to &quot;Decision and follow-up&quot;">​</a></h4><ul><li>Adopt / retain current version / repair and retest / stop:</li><li>Cases supporting the decision:</li><li>New regression cases and rerun scope:</li><li>Retest triggers after model, material, tool, or memory changes; last accepted version:</li><li>Permitted use / human takeover / withdrawal conditions:</li><li>Exit rehearsal after switching providers, disabling memory, or disconnecting tools:</li><li>Owner, review date, and record location:</li></ul><p>If no results are accepted, mark cost per accepted result “not calculable.” Preserve total incurred cost rather than replacing it with zero.</p><h2 id="worked-example-public-information-comparison" tabindex="-1">Worked example: public-information comparison <a class="header-anchor" href="#worked-example-public-information-comparison" aria-label="Permalink to &quot;Worked example: public-information comparison&quot;">​</a></h2><p>This hypothetical case matches the chapter: ten cases with one attempt each. A passes eight on first delivery, B passes nine, and both reach ten after human revision.</p><table tabindex="0"><thead><tr><th>Field</th><th>Example entry</th></tr></thead><tbody><tr><td>Change</td><td>Extraction prompt only; materials and tools remain identical</td></tr><tr><td>Mandatory conditions</td><td>Consequential figures have sources; missing prices must not be inferred</td></tr><tr><td>Failure B-07</td><td>Source gives no price; B writes “free”; reviewer corrects it to “not provided”</td></tr><tr><td>A costs</td><td>120 total minutes valued at RMB 60/hour, plus RMB 6 for tools: RMB 126</td></tr><tr><td>B costs</td><td>100 total minutes at the same valuation, plus RMB 8 for tools: RMB 108</td></tr><tr><td>Decision</td><td>Retain current scope; repair B before expanding use</td></tr><tr><td>Next action</td><td>Add missing, outdated, and conflicting price cases; rerun previously passing cases</td></tr><tr><td>Evidence limits</td><td>Small sample, one attempt per case; no production error-rate inference; repaired correctness does not establish autonomous reliability</td></tr></tbody></table><p>Store actual results in inspectable files. A completion record needs an artifact, test output, or system state, beyond the model&#39;s claim of success.</p><h2 id="turn-the-record-into-action" tabindex="-1">Turn the record into action <a class="header-anchor" href="#turn-the-record-into-action" aria-label="Permalink to &quot;Turn the record into action&quot;">​</a></h2><p>Fix one main error pattern per round and check for regressions. If the process remains unclear, revisit the <a href="https://byoungd.github.io/up/en/templates/ai-task-brief" target="_blank" rel="noreferrer">AI Task Brief</a>. Before offering the workflow as a service, use a <a href="https://byoungd.github.io/up/en/templates/startup-experiment" target="_blank" rel="noreferrer">Startup Experiment</a> to test demand separately from output quality.</p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/ai-evaluation" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-10-16. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',25)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
